int main(){ int m,n; cin>>m>>n; vector<string> g(m); for(auto&r:g)cin>>r; int r,c; long long Z; cin>>r>>c>>Z;
  // 0-1 free BFS from the start cell treated as a source; distance counts water cells entered
  vector<vector<int>> d(m,vector<int>(n,INT_MAX)); deque<pair<int,int>> q; int dr[4]={1,-1,0,0},dc[4]={0,0,1,-1};
  d[r][c]=0; q.push_back({r,c}); int best=INT_MAX;
  while(!q.empty()){ auto [a,b]=q.front(); q.pop_front();
    for(int k=0;k<4;k++){ int u=a+dr[k],v=b+dc[k]; if(u<0||v<0||u>=m||v>=n) continue;
      if(g[u][v]=='*' && g[a][b]=='.') best=min(best,d[a][b]);
      if(g[u][v]=='.' && d[a][b]+1<d[u][v]){ d[u][v]=d[a][b]+1; q.push_back({u,v}); } } }
  if(best==INT_MAX){ puts("unreachable"); return 0; }
  long long cost=1LL*best*(best+1); if(cost<=Z) cout<<Z-cost<<"\n"; else cout<<"died "<<cost-Z<<"\n"; }

